using Microsoft.Extensions.ML;
using Microsoft.ML;
using Microsoft.ML.Data;
using TicketClassifier.Models;

namespace TicketClassifier.Services;

/// <summary>
/// Wraps PredictionEnginePool and resolves the model's internal label ordering
/// so that score values are mapped to the correct category names.
/// </summary>
public sealed class TicketPredictionService
{
    private readonly PredictionEnginePool<TicketData, TicketPrediction> _pool;
    private string[]? _labelNames;

    public TicketPredictionService(PredictionEnginePool<TicketData, TicketPrediction> pool)
    {
        _pool = pool;
    }

    public (string Category, float Confidence, Dictionary<string, float> Scores) Predict(TicketData input)
    {
        var prediction = _pool.Predict(input);
        var labels = GetLabelNames();

        var scores = labels
            .Zip(prediction.Score)
            .ToDictionary(pair => pair.First, pair => pair.Second);

        return (prediction.Category, prediction.Score.Max(), scores);
    }

    private string[] GetLabelNames()
    {
        if (_labelNames is not null)
            return _labelNames;

        var engine = _pool.GetPredictionEngine();
        var scoreColumn = engine.OutputSchema["Score"];
        var slotNames = new VBuffer<ReadOnlyMemory<char>>();
        scoreColumn.GetSlotNames(ref slotNames);

        _labelNames = slotNames.DenseValues().Select(v => v.ToString()).ToArray();
        return _labelNames;
    }
}

